PRAGMA defer_foreign_keys=ON;
CREATE TABLE members_next (id TEXT PRIMARY KEY, board TEXT NOT NULL CHECK(board IN ('lucky','obsidus','staff')), name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', avatar_url TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL, team TEXT NOT NULL DEFAULT '');
INSERT INTO members_next(id,board,name,bio,avatar_url,updated_at,team) SELECT id,board,name,bio,avatar_url,updated_at,board FROM members;
DROP TABLE members;
ALTER TABLE members_next RENAME TO members;
ALTER TABLE posts ADD COLUMN like_adjustment INTEGER NOT NULL DEFAULT 0;
ALTER TABLE comments ADD COLUMN like_adjustment INTEGER NOT NULL DEFAULT 0;
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('ibex','staff','벡스 · 진우빈','팀장 / 특수 추적 · 게이트에서 돌아온 네 명을 이끄는 침착한 원칙주의자. 고위험 탈주자를 추적하고 유출된 오염을 제거한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim/925a54a2-f0be-41a7-aae6-4c9ac9cb7be6?v=2d7273','0','origin');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('slun','staff','슬런 · 이안 키스','특별관리 / 침식자 · 생존 가능성이 없다고 기록된 게이트에서 사흘 만에 귀환한 전직 센티넬. 기존 분류 체계로 설명할 수 없는 존재다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim/9d6c0284-1f5d-4b84-a05f-17ba4681ee43?v=b08b4b','0','origin');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('jaeshin','staff','신재신','잠입 / 정찰 / 트래퍼 · S급 게이트에서 생환한 귀환체. 보이지 않는 실로 퇴로를 막고, 자신의 손을 더럽히지 않은 채 전장을 움직인다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-1920x/5e792b7a-2bb5-4ad9-930d-ee996faf0f74?v=e22ec7','0','origin');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('bug','staff','버그 · 박하늘','디지털 간섭 / 통과자 · 세계를 데이터처럼 읽는 전 컴퓨터공학과 학생. 현실의 오류를 수정하듯 전자기기와 각성자의 파장에 간섭한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-1920x/cd7f80fd-5c63-4edb-af60-05a05319a1a4?v=8c686f','0','origin');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('binjo','staff','빈조','추적관리팀 팀장 / 가이드 · 차분한 지시로 현장을 통솔하는 비콘의 팀장. 극소수만 가능한 원거리 가이딩으로 팀의 균형을 잡는다.','https://cdn.caveduck.io/cdn-cgi/image/anim=true,dpr=2,f=auto,w=500/charim-standard/887d4f95-12c0-40c1-b827-94ccbf589259?v=096f43','0','beacon');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('levit','staff','레빗','현장 보호 / 센티넬 · 게이트 너머의 괴이를 불러 전장을 뒤집는 비콘의 전력. 예측하기 어려운 성향과 압도적인 돌파력을 함께 지녔다.','https://cdn.caveduck.io/cdn-cgi/image/anim=true,dpr=2,f=auto,w=500/charim-standard/a1895e22-07f8-481a-98ed-b3d363cdaa8f?v=7636cc','0','beacon');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('shepherd','staff','셰퍼드','추적 / 센티넬 · 불평은 먼저, 출동은 더 먼저. 미세한 흔적을 놓치지 않는 특전사 출신 추적 요원으로 약자 보호를 우선한다.','https://cdn.caveduck.io/cdn-cgi/image/anim=true,dpr=2,f=auto,w=500/charim-standard/ea9b437f-c347-474e-a47e-a4923283824a?v=b97ca9','0','beacon');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('seowon','staff','서원','추적 담당 / 가이드 · 부드러운 미소로 미등록 각성자의 경계를 낮추는 현장 요원. 차분한 대화와 끈기 있는 접촉으로 등록을 유도한다.','https://cdn.caveduck.io/cdn-cgi/image/anim=true,dpr=2,f=auto,w=500/charim-standard/c1093e19-7d5e-405c-9971-8e07729be127?v=3bfb4e','0','beacon');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('yeomyeong','staff','여명','사건 조사 / 센티넬 · 조용하고 순한 성격의 비콘 요원. 평상시에는 일반 업무를 맡고, 특정 사건이 발생하면 영매 능력을 발휘한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/f03e1ee5-fd0c-48c5-808f-aab3f3bb97e0?v=feffa7','0','beacon');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('wonhyeol','staff','원혈','팀장 / 전천후 · 「게이트를 닫는 자」. 단독 토벌이 가능한 최상위 센티넬로, 괴물 갱생 프로젝트의 보호자이자 교관이다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-1920x/d0063ac6-bfe1-4b51-a973-fe00a6796670?v=8ff5e2','0','shield');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('dain','staff','데인','힐러 / 서포트 · 실드의 회복과 감정 안정을 책임지는 요원. 누구에게나 이해를 먼저 건네며 팀의 완충 역할을 한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-1920x/b79c0f09-2c28-4e16-b112-c9c7f390dbe8?v=ad95d8','0','shield');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('jion','staff','지온','근접 파괴 / 탱커 · 방어보다 파괴에 특화된 전위 요원. 직선적인 전투 방식과 달리, 무방비한 존재 앞에서는 쉽게 흔들린다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-1920x/ad41bb13-f762-4eac-9eb6-6756f92a6a14?v=212a98','0','shield');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('sando','staff','산도','전술 분석 / 서포트 · 모든 전투를 확률로 읽는 실드의 분석가. 괴물 행동 패턴을 예측하고 팀의 판단을 뒷받침한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-1920x/3cb52ee6-19af-4fcd-91e7-00b48c3d2688?v=5f81e2','0','shield');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('baekjin','staff','백진','원거리 / 저격 · 두려움을 안고도 정확히 조준하는 신입 요원. 갱생 프로젝트의 대상과 함께 사회의 규칙을 다시 배워 간다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-1920x/0a1f1157-d278-4e52-b1f1-d19404f499ea?v=1b4222','0','shield');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('jaein','lucky','재인','팀장 / 원거리 딜러 · 정확한 궤도 제어와 화려한 전투로 팀을 이끄는 리더. 동료를 세심하게 챙기며 대중 앞에서도 당당하다.','https://cdn.caveduck.io/cdn-cgi/image/anim=true,dpr=2,f=auto,w=500/charim-1920x/b22dfb0d-817b-407e-9f90-18b4532a06fe?v=60dc4f','0','lucky');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('danjo','lucky','단조','근접 서포터 / 탱커 · 작은 체구와 달리 압도적인 내구도를 지닌 막내. 동료가 위험할 때 가장 먼저 몸을 던진다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/aaf6bab9-c6c8-4dd6-8736-8834b6b3b7d1?v=98f74b','0','lucky');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('unsae','lucky','운새','브루저 / 스트라이커 · 평소의 수줍고 나른한 모습과 전투 중의 폭발적인 힘이 공존하는 근접 요원.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/c29b6008-b93d-42cd-b2c6-2a0395682436?v=2235f6','0','lucky');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('yujin','lucky','유진','서브 딜러 / 특수 기술 · 차분하고 기품 있는 인상 속에 털털한 성격을 지녔다. 날카로운 금속 클로로 근접전을 지원한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/eb6ed7f9-0547-473f-b3d3-ebff85e0fa12?v=153d89','0','lucky');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('chabin','obsidus','차빈','팀장 / 근접 딜러 · 주변 물질을 무기와 이동 수단으로 바꾸는 옵시더스의 리더. 위험 앞에서 단호한 결단을 내린다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/aa0bfb68-ba52-41c4-a30e-4d1fa89b1a6d?v=de06e9','0','obsidus');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('hanho','obsidus','한호','원거리 서포터 / 정보조작 · 친절한 미소 뒤로 냉정하게 상황을 계산하는 저격수. 특수 탄환으로 적의 감각과 시야를 교란한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/73a7c2d2-11d7-45c9-bc87-cac25dbea410?v=fd93d0','0','obsidus');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('mohyun','obsidus','모현','메인 탱커 · 말보다 행동으로 사람을 지키는 방패. 거대한 체격과 달리 정원과 작은 동물을 좋아한다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim/958a0f49-5695-4b23-bfd9-5ea2e427957e?v=f02e09','0','obsidus');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('yuhwan','obsidus','유환','공격 / 수리 · 다수의 기계팔과 빠른 자가 수리로 전투를 이어가는 사이보그 요원. 유쾌하고 인간적인 면모를 지녔다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/23d57970-1056-49d8-a845-c696c94cbb9d?v=c7a772','0','obsidus');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('poker','staff','포커 · 강준겸','팀장 / 데크 소환 · 고위험 작전의 판을 읽고 기물을 배치하는 블랙잭 팀장. 전술과 각성 능력을 결합해 팀의 돌입을 지휘한다.','https://cdn.caveduck.io/cdn-cgi/image/anim=true,dpr=2,f=auto,w=500/charim-standard/c8574255-991d-416b-bf99-2dfac0c30357?v=e82871','0','blackjack');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('dealer','staff','딜러','작전 중개 / 링크 · 작전 중 팀원들의 판단과 정보를 연결한다. 링크는 임무 수행 중에만 운용한다.','https://onlyunlimit.github.io/assets/art/personnel-placeholder.svg','0','blackjack');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('rear','staff','리어','후면 방어 / 리어가드 · 지정한 영역의 움직임을 감지하고 후면을 지킨다. 팀이 안전하게 후퇴할 시간을 확보한다.','https://onlyunlimit.github.io/assets/art/personnel-placeholder.svg','0','blackjack');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('panden','staff','판덴','관측 / 원거리 탐지 · 시야 너머 현장의 인원과 특징을 파악하는 관측 담당. 능력 소모에 따라 탐지 정확도가 달라진다.','https://onlyunlimit.github.io/assets/art/personnel-placeholder.svg','0','blackjack');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('siso','staff','시소','브리처 / 인질 회수 · 검은 고양이 출신 수인. 빠루로 진입로를 열고 인질을 안전한 곳으로 회수하는 블랙잭의 막내다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim-standard/dc108656-4e56-4d1a-a1c4-b2c18fa8eac4?v=8172d8','0','blackjack');
INSERT OR IGNORE INTO members(id,board,name,bio,avatar_url,updated_at,team) VALUES ('joker','staff','조커','데크 연계 / 자율 협력 · 포커의 덱에 연결된 자율적인 존재. 일반 소속 요원과 구분되며, 작전 참여는 조커 자신의 의지에 달려 있다.','https://cdn.caveduck.io/cdn-cgi/image/dpr=2,f=auto,w=800/charim/23a1945e-9683-40d8-8cd0-ae2612641cc3?v=9c0c9c','0','blackjack');

